"use client";

import "../../styles/whatiuse-base.css";
import "../../styles/components/action-list.css";
import { MagnifyingGlass } from "@phosphor-icons/react";
import { useId, useMemo, useState, type KeyboardEvent, type ReactNode } from "react";
import type { BehaviorContract } from "../../lib/behavior-contract";
import { cn } from "../../lib/cn";

export const actionListContract: BehaviorContract = {
  input: ["Typing", "Arrow keys", "Pointer hover", "Pointer click"],
  origin: "Selection begins at the first enabled result and follows the query.",
  enter: "Results update in place; the active row uses a quiet monochrome fill.",
  active: "Input retains DOM focus while aria-activedescendant tracks the active option.",
  exit: "Enter or click invokes one action and clears transient selection state.",
  interruption: "An empty result set keeps the query editable and announces no results.",
  keyboard: ["Arrow Up/Down: move", "Home/End: jump", "Enter: run", "Escape: clear query"],
  reducedMotion: "Filtering and selection update without animated displacement.",
};

export type ActionListItem = {
  id: string;
  label: string;
  description?: string;
  icon?: ReactNode;
  shortcut?: string;
  disabled?: boolean;
  loading?: boolean;
  variant?: "default" | "danger";
  inactiveReason?: string;
};

export type ActionListProps = {
  items: readonly ActionListItem[];
  onAction: (item: ActionListItem) => void;
  placeholder?: string;
  emptyMessage?: string;
  className?: string;
  autoFocus?: boolean;
  defaultQuery?: string;
};

export function ActionList({ items, onAction, placeholder = "Search actions…", emptyMessage = "No actions found", className, autoFocus, defaultQuery = "" }: ActionListProps) {
  const listId = useId();
  const [query, setQuery] = useState(defaultQuery);
  const filtered = useMemo(() => {
    const normalized = query.trim().toLocaleLowerCase();
    if (!normalized) return items;
    return items.filter((item) => `${item.label} ${item.description ?? ""}`.toLocaleLowerCase().includes(normalized));
  }, [items, query]);
  const enabledIndices = filtered.map((item, index) => ({ item, index })).filter(({ item }) => !item.disabled && !item.loading).map(({ index }) => index);
  const [activeIndex, setActiveIndex] = useState(0);
  const safeActiveIndex = enabledIndices.includes(activeIndex) ? activeIndex : (enabledIndices[0] ?? -1);

  const move = (direction: 1 | -1) => {
    if (!enabledIndices.length) return;
    const position = enabledIndices.indexOf(safeActiveIndex);
    const nextPosition = (position + direction + enabledIndices.length) % enabledIndices.length;
    setActiveIndex(enabledIndices[nextPosition]);
  };

  const runActive = () => {
    const item = filtered[safeActiveIndex];
    if (item && !item.disabled && !item.loading) onAction(item);
  };

  const onKeyDown = (event: KeyboardEvent<HTMLInputElement>) => {
    if (event.key === "ArrowDown") { event.preventDefault(); move(1); }
    if (event.key === "ArrowUp") { event.preventDefault(); move(-1); }
    if (event.key === "Home" && enabledIndices.length) { event.preventDefault(); setActiveIndex(enabledIndices[0]); }
    if (event.key === "End" && enabledIndices.length) { event.preventDefault(); setActiveIndex(enabledIndices.at(-1) ?? 0); }
    if (event.key === "Enter") { event.preventDefault(); runActive(); }
    if (event.key === "Escape" && query) { event.preventDefault(); setQuery(""); setActiveIndex(0); }
  };

  return (
    <div className={cn("whatiuse-action-list", className)}>
      <div className="whatiuse-action-list__search">
        <MagnifyingGlass aria-hidden="true" />
        <input
          value={query}
          autoFocus={autoFocus}
          onChange={(event) => { setQuery(event.target.value); setActiveIndex(0); }}
          onKeyDown={onKeyDown}
          placeholder={placeholder}
          aria-label="Search actions"
          role="combobox"
          aria-autocomplete="list"
          aria-expanded="true"
          aria-controls={listId}
          aria-activedescendant={safeActiveIndex >= 0 ? `${listId}-${filtered[safeActiveIndex]?.id}` : undefined}
        />
        <kbd aria-label="Command K">⌘K</kbd>
      </div>
      <div id={listId} className="whatiuse-action-list__items" role="listbox" aria-label="Actions">
        {filtered.map((item, index) => (
          <div
            id={`${listId}-${item.id}`}
            key={item.id}
            role="option"
            aria-selected={index === safeActiveIndex}
            aria-disabled={item.disabled || item.loading || undefined}
            className="whatiuse-action-list__item"
            data-active={index === safeActiveIndex || undefined}
            data-disabled={item.disabled || undefined}
            data-loading={item.loading || undefined}
            data-variant={item.variant}
            title={item.inactiveReason}
            onPointerEnter={() => !item.disabled && !item.loading && setActiveIndex(index)}
            onClick={() => !item.disabled && !item.loading && onAction(item)}
          >
            <span className="whatiuse-action-list__icon" aria-hidden="true">{item.icon}</span>
            <span className="whatiuse-action-list__copy">
              <span>{item.label}</span>
              {(item.description || item.inactiveReason) && <small>{item.inactiveReason ?? item.description}</small>}
            </span>
            {item.loading ? <span className="whatiuse-spinner" aria-hidden="true" /> : item.shortcut && <kbd>{item.shortcut}</kbd>}
          </div>
        ))}
      </div>
      {!filtered.length && <div className="whatiuse-action-list__empty" role="status">{emptyMessage}</div>}
    </div>
  );
}

/* Generated from src/foundation.css and src/styles.css. Do not edit directly. */

@layer whatiuse.tokens, whatiuse.base, whatiuse.components;

@layer whatiuse.components {
.whatiuse-action-list kbd { display: inline-flex; flex: 0 0 auto; align-items: center; justify-content: center; color: var(--whatiuse-ink-tertiary); font-family: inherit; font-size: 10px; line-height: 1; white-space: nowrap; }

.whatiuse-spinner { width: 13px; height: 13px; border: 1.5px solid currentColor; border-right-color: transparent; border-radius: 50%; animation: whatiuse-spin 0.75s linear infinite; }

.whatiuse-action-list { width: min(480px, 100%); overflow: hidden; border: 1px solid var(--whatiuse-border); border-radius: 9px; background: var(--whatiuse-surface); box-shadow: 0 18px 52px oklch(0.17 0.004 var(--whatiuse-neutral-h) / 0.1), 0 3px 12px oklch(0.17 0.004 var(--whatiuse-neutral-h) / 0.045); }

.whatiuse-action-list__search { display: flex; height: 39px; align-items: center; gap: 8px; padding: 0 10px; border-bottom: 1px solid var(--whatiuse-border-subtle); }

.whatiuse-action-list__search > svg { width: 14px; height: 14px; color: var(--whatiuse-fg-subtle); }

.whatiuse-action-list__search input { width: 100%; min-width: 0; height: 100%; border: 0; outline: 0; color: var(--whatiuse-ink); font-size: 13.5px; }

.whatiuse-action-list__search input::placeholder { color: var(--whatiuse-fg-subtle); }

.whatiuse-action-list__search kbd { min-width: 28px; height: 23px; padding: 0 5px; border: 1px solid var(--whatiuse-border); border-radius: 4px; background: #fafafa; }

.whatiuse-action-list__items { display: grid; gap: 1px; padding: 4px; }

.whatiuse-action-list__item { display: grid; grid-template-columns: 24px minmax(0, 1fr) auto; align-items: center; min-height: 43px; padding: 4px 8px; border-radius: 5px; cursor: default; }

.whatiuse-action-list__item[data-active] { background: var(--whatiuse-hover); }

.whatiuse-action-list__item[data-disabled] { opacity: 0.38; }

.whatiuse-action-list__item[data-loading] { color: var(--whatiuse-fg-subtle); cursor: wait; }

.whatiuse-action-list__item[data-variant="danger"] .whatiuse-action-list__copy > span,
.whatiuse-action-list__item[data-variant="danger"] .whatiuse-action-list__icon { color: var(--whatiuse-fg-danger); font-weight: 560; }

.whatiuse-action-list__icon { display: inline-flex; color: var(--whatiuse-fg-muted); }

.whatiuse-action-list__icon svg { width: 14px; height: 14px; }

.whatiuse-action-list__copy { display: grid; gap: 1px; color: var(--whatiuse-ink); font-size: 13.5px; }

.whatiuse-action-list__copy small { color: var(--whatiuse-ink-tertiary); font-size: 11.5px; }

.whatiuse-action-list__item > kbd { color: var(--whatiuse-fg-subtle); }

.whatiuse-action-list__empty { padding: 30px 10px; color: var(--whatiuse-ink-tertiary); font-size: 12px; text-align: center; }

@media (forced-colors: active) {
.whatiuse-action-list { forced-color-adjust: none; border-color: CanvasText; background: Canvas; color: CanvasText; }

.whatiuse-action-list__item[data-active] { outline: 2px solid Highlight; outline-offset: -2px; }
}

.whatiuse-action-list {
  scrollbar-color: var(--whatiuse-scrollbar-thumb) transparent;
  scrollbar-width: thin;
}

.whatiuse-action-list::-webkit-scrollbar { width: 10px; height: 10px; }

.whatiuse-action-list::-webkit-scrollbar-track { background: transparent; }

.whatiuse-action-list::-webkit-scrollbar-thumb {
  border: 3px solid transparent;
  border-radius: 999px;
  background: var(--whatiuse-scrollbar-thumb);
  background-clip: padding-box;
}

.whatiuse-action-list::-webkit-scrollbar-thumb:hover { background: var(--whatiuse-scrollbar-thumb-hover); background-clip: padding-box; }

.whatiuse-action-list__search kbd { background: var(--whatiuse-subtle); color: var(--whatiuse-ink-secondary); }

@media (forced-colors: active) {
.whatiuse-action-list { scrollbar-color: auto; }
}

@media (prefers-reduced-motion: reduce) {
.whatiuse-spinner { animation-duration: 2.4s; }
}

@keyframes whatiuse-spin { to { transform: rotate(360deg); } }
}
